def sha(data): return hashlib.sha256(data).hexdigest()
def run(args, cwd):
    print('Running:', ' '.join(map(str,args)), flush=True)
    subprocess.run(args,cwd=cwd,check=True)

def main():
    root=Path.cwd()
    if not (root/'backend/market_lab/midpoint_strategy/live_shadow_ui.py').is_file() or not (root/'frontend/package.json').is_file():
        raise SystemExit('STOP: run from RB-ITOS-AI repository root')
    desired={rel:zlib.decompress(base64.b85decode(encoded)) for rel,encoded in PAYLOAD.items()}
    changes=[]
    for rel,data in desired.items():
        path=root/rel
        current=path.read_bytes() if path.exists() else None
        if current==data: continue
        if (sha(current) if current is not None else None)!=BASELINE[rel]:
            raise SystemExit(f'STOP: source differs from reviewed baseline: {rel}; no changes applied')
        changes.append((rel,path,data,current))
    backup=root/'data/backups'/('midpoint-m25b-sidebar-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
    backup.mkdir(parents=True,exist_ok=False)
    for rel,path,_,current in changes:
        if current is not None:
            target=backup/rel; target.parent.mkdir(parents=True,exist_ok=True); target.write_bytes(current)
    try:
        for _,path,data,_ in changes:
            path.parent.mkdir(parents=True,exist_ok=True); path.write_bytes(data)
        python=root/'.venv/bin/python'
        run([str(python),'-m','pytest','-q','tests/test_midpoint_m25b_option_observation.py','tests/test_midpoint_m3_live_shadow_ui.py','tests/test_live_loading_integrity_guard.py'],root)
        run(['npm','run','build'],root/'frontend')
        run(['git','diff','--check'],root)
    except Exception as exc:
        for _,path,_,current in changes:
            if current is None: path.unlink(missing_ok=True)
            else: path.write_bytes(current)
        raise SystemExit(f'STOP: validation failed ({exc}); source restored; API and workers untouched') from exc
    print(f'PASS: {len(changes)} source files validated; frontend built; API and workers untouched.')
    print('Backup:',backup)
    print('Option tape still needs exact expiry and after-market acquisition.')
if __name__=='__main__': main()
